corporate_design.toad_component_blueprint:
canvas {
  size: 880px 580px;
  fill: #FAF6EF;
  font-family: "Barlow, serif";
}

>timber = #261C14;
>gold = #D97706;
>brick = #991B1B;

rect #guildCard {
  at: center of canvas;
  size: 800px 480px;
  fill: #FFFFFF;
  stroke: >timber;
  stroke-width: 2px;
  radius: 4px;
}

text #guildTitle {
  at: top center of #guildCard offset 0px 40px;
  content: "ZIMMEREI EICHENLAUB • SEIT 1954";
  font-size: 16px;
  font-weight: 700;
  color: >gold;
}

text #mainMotto {
  at: below #guildTitle offset 16px;
  content: "Gekonntes Holzhandwerk & Fachwerk-Restaurierung";
  font-size: 26px;
  font-weight: 700;
  color: >timber;
}

text #serviceDetails {
  at: below #mainMotto offset 20px;
  size: 680px;
  content: "Dachstühle • Carports • Gauben • Altbausanierung mit Eichenholz aus heimischer Forstwirtschaft.";
  font-size: 15px;
  color: #4A3A2E;
}
